import type { ChapterData, DocumentData, ResearchFolder } from "./publish/types";
import type { DocumentMeta, PageKind, Relation } from "./story-meta";
import { createWikiMentionMatcher } from "./wiki-mentions";

/** A relation together with the id of the page that stores it. */
export type SourcedRelation = { source: string; relation: Relation };

/** The relation fields a caller sets; the id is generated by `addRelation`. */
export type RelationInput = Omit<Relation, "id">;

const FOLDER_KINDS: Record<string, PageKind> = {
  characters: "character",
  places: "place",
  organisations: "organisation",
  organizations: "organisation",
  items: "item"
};

/**
 * Page kind from `meta.kind`, falling back to the title of the page's folder
 * when the author did not set one explicitly.
 */
export function pageKind(doc: DocumentData, folders: readonly ResearchFolder[]): PageKind {
  if (doc.meta?.kind) return doc.meta.kind;
  const folder = doc.folderId ? folders.find((entry) => entry.id === doc.folderId) : undefined;
  if (!folder) return "other";
  return FOLDER_KINDS[folder.title.trim().toLowerCase()] ?? "other";
}

/** Wiki pages that count as characters, either declared or by folder. */
export function characterPages(
  documents: readonly DocumentData[],
  folders: readonly ResearchFolder[]
): DocumentData[] {
  return documents.filter(
    (doc) => doc.space === "Wiki" && !doc.trashed && pageKind(doc, folders) === "character"
  );
}

/** All stored relations, each paired with the id of its source page. */
export function relationsOf(documents: readonly DocumentData[]): SourcedRelation[] {
  const relations: SourcedRelation[] = [];
  for (const doc of documents) {
    if (doc.trashed) continue;
    for (const relation of doc.meta?.relations ?? []) {
      relations.push({ source: doc.id, relation });
    }
  }
  return relations;
}

/**
 * Derives the incoming direction of every relation. The reverse entry lives on
 * the target page and points back at the source; it is never stored.
 */
export function reverseView(relations: readonly SourcedRelation[]): SourcedRelation[] {
  return relations.map(({ source, relation }) => ({
    source: relation.to,
    relation: { ...relation, id: `reverse:${relation.id}`, to: source }
  }));
}

/**
 * Whether a relation holds in a chapter. Bounds are inclusive and compared by
 * chapter position. A bound that no longer resolves to a chapter (for example
 * after deleting it) is ignored, so the relation stays visible.
 */
export function relationActiveAt(
  relation: Relation,
  chapterId: string,
  chapters: readonly ChapterData[]
): boolean {
  const indexById = new Map(chapters.map((chapter, index) => [chapter.id, index]));
  const current = indexById.get(chapterId);
  if (current === undefined) return false;
  const from = relation.from ? indexById.get(relation.from) : undefined;
  if (from !== undefined && current < from) return false;
  const until = relation.until ? indexById.get(relation.until) : undefined;
  if (until !== undefined && current > until) return false;
  return true;
}

/**
 * Replaces the relation list of one page without touching the rest of the
 * document. The `meta` key is dropped when nothing is left in it.
 */
function replaceRelations(
  documents: readonly DocumentData[],
  sourceId: string,
  replace: (relations: readonly Relation[]) => Relation[]
): DocumentData[] {
  return documents.map((doc) => {
    if (doc.id !== sourceId) return doc;
    const relations = replace(doc.meta?.relations ?? []);
    const meta: DocumentMeta = { ...doc.meta };
    if (relations.length > 0) meta.relations = relations;
    else delete meta.relations;
    if (Object.keys(meta).length === 0) {
      const next = { ...doc };
      delete next.meta;
      return next;
    }
    return { ...doc, meta };
  });
}

/** Appends a relation to a page, generating its id with the injected factory. */
export function addRelation(
  documents: readonly DocumentData[],
  sourceId: string,
  relation: RelationInput,
  createId: () => string
): DocumentData[] {
  const entry: Relation = { ...relation, id: createId() };
  return replaceRelations(documents, sourceId, (relations) => [...relations, entry]);
}

/** Merges a patch into one stored relation, keeping its id. */
export function updateRelation(
  documents: readonly DocumentData[],
  sourceId: string,
  relationId: string,
  patch: Partial<RelationInput>
): DocumentData[] {
  return replaceRelations(documents, sourceId, (relations) =>
    relations.map((relation) =>
      relation.id === relationId ? { ...relation, ...patch, id: relation.id } : relation
    )
  );
}

/** Removes one relation from a page. */
export function removeRelation(
  documents: readonly DocumentData[],
  sourceId: string,
  relationId: string
): DocumentData[] {
  return replaceRelations(documents, sourceId, (relations) =>
    relations.filter((relation) => relation.id !== relationId)
  );
}

export type AppearanceMode = "confirmed" | "auto";

export type SceneAppearance = {
  sceneId: string;
  mode: AppearanceMode;
};

/** One page with every scene it appears in, in story order. */
export type PageAppearances = {
  pageId: string;
  kind: PageKind;
  scenes: SceneAppearance[];
  sceneCount: number;
  confirmedCount: number;
  autoCount: number;
  /** Chapter of the first/last appearance; `null` when the page appears nowhere. */
  firstChapterId: string | null;
  lastChapterId: string | null;
  /** Index into the project chapter list; `-1` when the page appears nowhere. */
  firstChapterIndex: number;
  lastChapterIndex: number;
};

function emptyAppearances(pageId: string, kind: PageKind): PageAppearances {
  return {
    pageId,
    kind,
    scenes: [],
    sceneCount: 0,
    confirmedCount: 0,
    autoCount: 0,
    firstChapterId: null,
    lastChapterId: null,
    firstChapterIndex: -1,
    lastChapterIndex: -1
  };
}

function recordAppearance(
  entry: PageAppearances,
  sceneId: string,
  mode: AppearanceMode,
  chapterId: string,
  chapterIndex: number
): void {
  entry.scenes.push({ sceneId, mode });
  entry.sceneCount += 1;
  if (mode === "confirmed") entry.confirmedCount += 1;
  else entry.autoCount += 1;
  if (entry.firstChapterId === null) {
    entry.firstChapterId = chapterId;
    entry.firstChapterIndex = chapterIndex;
  }
  entry.lastChapterId = chapterId;
  entry.lastChapterIndex = chapterIndex;
}

/**
 * Collects, for every wiki page, the scenes it appears in. A scene confirms a
 * page through `meta.characters`; otherwise a title or alias mention marks it
 * as detected ("auto"). Scenes are visited in chapter order, then in document
 * order, so the resulting lists are in story order.
 */
export function appearances(
  documents: readonly DocumentData[],
  chapters: readonly ChapterData[],
  folders: readonly ResearchFolder[]
): Map<string, PageAppearances> {
  const pages = documents.filter((doc) => doc.space === "Wiki" && !doc.trashed);
  const result = new Map<string, PageAppearances>();
  const articles: { title: string; pageId: string }[] = [];
  for (const page of pages) {
    result.set(page.id, emptyAppearances(page.id, pageKind(page, folders)));
    articles.push({ title: page.title, pageId: page.id });
    for (const alias of page.meta?.aliases ?? []) articles.push({ title: alias, pageId: page.id });
  }

  const scenesByChapter = new Map<string, DocumentData[]>();
  for (const doc of documents) {
    if (doc.trashed || doc.space === "Wiki" || !doc.chapterId) continue;
    const scenes = scenesByChapter.get(doc.chapterId);
    if (scenes) scenes.push(doc);
    else scenesByChapter.set(doc.chapterId, [doc]);
  }

  const match = createWikiMentionMatcher(articles);
  chapters.forEach((chapter, chapterIndex) => {
    for (const scene of scenesByChapter.get(chapter.id) ?? []) {
      const confirmed = new Set(scene.meta?.characters ?? []);
      const appearing = new Set<string>(confirmed);
      for (const mention of match(scene.content)) appearing.add(mention.article.pageId);
      for (const pageId of appearing) {
        const entry = result.get(pageId);
        if (!entry) continue;
        recordAppearance(
          entry,
          scene.id,
          confirmed.has(pageId) ? "confirmed" : "auto",
          chapter.id,
          chapterIndex
        );
      }
    }
  });

  return result;
}

/** Two pages with the number of scenes they share. `key` is `a|b` with sorted ids. */
export type PagePair = { a: string; b: string; key: string; count: number };

function pagePair(a: string, b: string): { a: string; b: string; key: string } {
  return a <= b ? { a, b, key: `${a}|${b}` } : { a: b, b: a, key: `${b}|${a}` };
}

/** Counts, for every pair of pages, the scenes both of them appear in. */
export function coAppearanceCounts(
  appearances: ReadonlyMap<string, PageAppearances>
): PagePair[] {
  const pagesByScene = new Map<string, Set<string>>();
  for (const entry of appearances.values()) {
    for (const scene of entry.scenes) {
      const pages = pagesByScene.get(scene.sceneId);
      if (pages) pages.add(entry.pageId);
      else pagesByScene.set(scene.sceneId, new Set([entry.pageId]));
    }
  }

  const counts = new Map<string, PagePair>();
  for (const pages of pagesByScene.values()) {
    const ids = [...pages];
    for (let first = 0; first < ids.length; first += 1) {
      for (let second = first + 1; second < ids.length; second += 1) {
        const pair = pagePair(ids[first], ids[second]);
        const existing = counts.get(pair.key);
        if (existing) existing.count += 1;
        else counts.set(pair.key, { ...pair, count: 1 });
      }
    }
  }

  return [...counts.values()].sort(
    (left, right) =>
      right.count - left.count || (left.key < right.key ? -1 : left.key > right.key ? 1 : 0)
  );
}

/**
 * Pairs that share at least `minScenes` scenes but are not linked yet, in
 * either direction. Dismissed pairs stay hidden. Suggestions are never
 * applied automatically.
 */
export function suggestRelations(
  appearances: ReadonlyMap<string, PageAppearances>,
  relations: readonly SourcedRelation[],
  dismissed: readonly string[],
  minScenes = 3
): PagePair[] {
  const dismissedKeys = new Set(dismissed);
  const linkedKeys = new Set(
    relations.map(({ source, relation }) => pagePair(source, relation.to).key)
  );
  return coAppearanceCounts(appearances).filter(
    (pair) =>
      pair.count >= minScenes && !dismissedKeys.has(pair.key) && !linkedKeys.has(pair.key)
  );
}
